for _loc in locations:
    for _site in _loc.get("sites", []):
        if _site["id"] in SITE_ABOUT:
            _site["about"] = SITE_ABOUT[_site["id"]]
_missing = sorted({s["id"] for l in locations for s in l.get("sites", []) if s["kind"] != "home" and s["id"] not in SITE_ABOUT})
assert not _missing, f"sites without words for the maps: {_missing}"
